// spec: .qa/e2e/specs/monitoring.md (3.2) · кейс: .qa/tests/monitoring/MON-029.md
// seed: tests/seed.user.spec.ts
// Веб-мок ?mock=hot: термостатус 3 (SEVERE), 44°C ~30 с → настоящий перегрев.
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, endMonitoring } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, `../../../auth/${process.env.QA_MON_AUTH || 'user'}.json`) });
test.setTimeout(150_000);

test.describe('Сбои мониторинга (мок)', () => {
  test('SEVERE: сбой «הטלפון התחמם» · «לא במעקב» с советами #56611b @android @data', async ({ page }) => {
    await startMonitoring(page, 'hot');

    // Сбой «הטלפון התחמם» (F-21 AC5; S-14 AC1/AC3) — после ~20 с непрерывного SEVERE
    await expect(page.getByText('הטלפון התחמם').filter({ visible: true }).first()).toBeVisible({ timeout: 50_000 });
    await expect(page.getByText('הטלפון חם מדי כדי להמשיך.').filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText(/הבריכה לא במעקב — השגיחו עליה בעצמכם/).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText('העבירו את הטלפון לצל').filter({ visible: true }).first()).toBeVisible();
    // При SEVERE — сбой, а не баннер умеренного нагрева
    await expect(page.getByText(/הטלפון מתחמם\. הניטור ממשיך/).filter({ visible: true })).toHaveCount(0);

    await endMonitoring(page);
  });
});
